### **Step 2: Use Google Apps Script in Google Sheets**
1. **Open Google Sheets** and go to **Extensions > Apps Script**.
2. **Create a new script** and paste the following code:

```javascript
function getCompanyData(companyName) {
  const apiKey = "YOUR_API_KEY"; // Replace with your API key
  const cseId = "YOUR_CSE_ID"; // Replace with your CSE ID
  const domainQuery = `site:*.${companyName} OR site:www.${companyName} OR site:*.${companyName.toLowerCase()}`;
  const marketingQuery = `Head of Marketing ${companyName} OR CMO ${companyName} OR Director of Marketing ${companyName}`;
  const linkedInQuery = `${companyName} LinkedIn`;

  // Get domain
  const domainRes = searchCSE(domainQuery, apiKey, cseId);
  const domain = domainRes ? domainRes[0].title : "N/A";

  // Get marketing head name
  const marketingRes = searchCSE(marketingQuery, apiKey, cseId);
  const marketingName = marketingRes ? marketingRes[0].title : "N/A";

  // Get LinkedIn profile
  const linkedInRes = searchCSE(linkedInQuery, apiKey, cseId);
  const linkedInUrl = linkedInRes ? linkedInRes[0].link : "N/A";

  return [domain, marketingName, linkedInUrl];
}

function searchCSE(query, apiKey, cseId) {
  const url = `https://www.googleapis.com/customsearch/v1?q=${encodeURIComponent(query)}&key=${apiKey}&cx=${cseId}&num=1`;
  const response = UrlFetchApp.fetch(url);
  const json = JSON.parse(response.getContentText());
  return json.items || [];
}
```

3. **Save the script** and close the editor.

